    string shortestBeautifulSubstring(string s, int k) {
        int n = s.length();
        string result = "";
        int minLen = INT_MAX;

        int left = 0, ones = 0;
        for (int right = 0; right < n; ++right) {
            if (s[right] == '1') {
                ones++;
            }

            // shrink from left while window has more than k ones,
