                    ones--;
                }
                left++;
            }

            if (ones == k) {
                int len = right - left + 1;
                string candidate = s.substr(left, len);
                if (len < minLen || (len == minLen && candidate < result)) {
                    minLen = len;
                    result = candidate;
                }
            }
        }

        return result;
    }
};

